/**
 * US labor market churn: hires, separations, and the quit engine (2026).
 *
 * Core question: How fast are US workers hired and separated each month,
 * and which industries drive quits versus layoffs in the post-pandemic market?
 *
 * Anchors: BLS JOLTS news release for June 2026 (USDL-26-1289, published
 * Aug 4, 2026); FRED monthly rates JTSHIR / JTSQUR / JTSTSR / JTSJOR /
 * JTSLDR (seasonally adjusted, total nonfarm) through June 2026.
 */

export type Confidence = "disclosed" | "derived";

export const SOURCE_NOTE =
  "Levels and industry rates are seasonally adjusted BLS JOLTS figures from the June 2026 news release (preliminary). Monthly national rate paths are FRED mirrors of BLS JOLTS (JTSHIR hires rate, JTSQUR quits rate, JTSLDR layoffs-and-discharges rate, JTSTSR total separations rate, JTSJOR job openings rate). Quit share of separations = quits ?? total separations (derived). Churn rate = hires rate + separations rate (derived analytical sum, not a BLS published series). Establishment size-class cells are total private only. Confidence: release cells disclosed; quit-share and churn sums derived.";

export const SOURCES = [
  {
    label: "BLS ??? Job Openings and Labor Turnover Survey news release (June 2026)",
    url: "https://www.bls.gov/news.release/jolts.htm",
  },
  {
    label: "BLS ??? JOLTS program home",
    url: "https://www.bls.gov/jlt/",
