"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  HEADLINE,
  INDUSTRIES,
  REGIONS,
  SEPARATION_COMPOSITION,
  SIZE_CLASSES,
  SOURCE_NOTE,
  VIZ_MARKERS,
  churnRate,
  filterMonthlyByEra,
  quitMinusLayoff,
  quitShare,
  scatterPairs,
  type EraId,
  type IndustrySector,
} from "@/data/us-labor-market-churn-jolts-2026-data";

// viz-types: multi-line flow tape, diverging quit-layoff bars, quit??layoff scatter, size-class grouped bars, separation donut | layout: default

type PanelId = "flow" | "industry" | "scatter" | "size" | "compose";

type SectorFilter = "all" | IndustrySector;

type MetricId = "rates" | "levels" | "quitShare";

const COLORS = {
  hires: "#0369a1",
  quits: "#0f766e",
  layoffs: "#b91c1c",
  separations: "#7c3aed",
  openings: "#ca8a04",
  navy: "#0f172a",
  grid: "#e2e8f0",
  mute: "#94a3b8",
};

const PANEL_OPTIONS: { id: PanelId; label: string }[] = [
  { id: "flow", label: "Flow tape" },
  { id: "industry", label: "Industry mix" },
  { id: "scatter", label: "Quit ?? layoff" },
  { id: "size", label: "Size class" },
  { id: "compose", label: "Separation mix" },
];

const ERA_OPTIONS: { id: EraId; label: string }[] = [
  { id: "all", label: "Full path" },
  { id: "pre", label: "Pre-2020" },
  { id: "shock", label: "2020 shock" },
  { id: "resignation", label: "Resignation" },
  { id: "unwind", label: "2023???26 unwind" },
];

const SECTOR_OPTIONS: { id: SectorFilter; label: string }[] = [
  { id: "all", label: "All industries" },
  { id: "goods", label: "Goods" },
  { id: "trade-transport", label: "Trade & TWU" },
  { id: "info-finance", label: "Info & finance" },
  { id: "professional", label: "Prof. services" },
  { id: "education-health", label: "Health" },
  { id: "leisure", label: "Leisure" },
  { id: "government", label: "Government" },
];

const METRIC_OPTIONS: { id: MetricId; label: string }[] = [
  { id: "rates", label: "Rates %" },
  { id: "levels", label: "Levels (000s)" },
  { id: "quitShare", label: "Quit share" },
];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-2.5 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function fmtPct(n: number, digits = 1) {
  return `${n.toFixed(digits)}%`;
}

function fmtK(n: number) {
  return n >= 1000 ? `${(n / 1000).toFixed(1)}M` : `${n.toLocaleString()}k`;
}

export function UsLaborMarketChurnJolts2026Dashboard() {
  const [panel, setPanel] = useState<PanelId>("flow");
  const [era, setEra] = useState<EraId>("all");
  const [sector, setSector] = useState<SectorFilter>("all");
  const [metric, setMetric] = useState<MetricId>("rates");

  const flowData = useMemo(() => filterMonthlyByEra(era), [era]);

  const industryRows = useMemo(() => {
    const base =
      sector === "all"
        ? INDUSTRIES
        : INDUSTRIES.filter((i) => i.sector === sector);
    return [...base].sort((a, b) => quitMinusLayoff(b) - quitMinusLayoff(a));
  }, [sector]);

  const industryChart = useMemo(() => {
    return industryRows.map((i) => {
      if (metric === "levels") {
        return {
          name: i.short,
          quits: i.quits,
          layoffs: i.layoffs,
          hires: i.hires,
        };
      }
      if (metric === "quitShare") {
        return {
          name: i.short,
          quitShare: Math.round(quitShare(i) * 1000) / 10,
          layoffShare: Math.round((i.layoffs / i.separations) * 1000) / 10,
        };
      }
      return {
        name: i.short,
        quits: i.quitsRate,
        layoffs: -i.layoffsRate,
        hires: i.hiresRate,
        delta: quitMinusLayoff(i),
      };
    });
  }, [industryRows, metric]);

  const scatterData = useMemo(() => scatterPairs(sector), [sector]);

  const sizeData = useMemo(() => {
    return SIZE_CLASSES.map((s) => ({
      name: s.label,
      hires: s.hiresRate,
      quits: s.quitsRate,
      layoffs: s.layoffsRate,
      openings: s.openingsRate,
    }));
  }, []);

  const regionData = useMemo(
    () =>
      REGIONS.map((r) => ({
        name: r.label,
        quits: r.quitsRate,
        layoffs: r.layoffsRate,
      })),
    [],
  );

  return (
    <div
      className="space-y-4"
      data-viz={VIZ_MARKERS.root}
      data-testid={VIZ_MARKERS.root}
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-teal-950 px-5 py-4 text-white shadow-sm">
        <p className="text-xs font-semibold uppercase tracking-wider text-teal-200/80">
          BLS JOLTS ?? {HEADLINE.asOfLabel}
        </p>
        <p className="mt-1 text-xl font-bold tracking-tight sm:text-2xl">
          {fmtK(HEADLINE.quitsThousands)} quits ?? {fmtPct(HEADLINE.quitsRate)}{" "}
          rate ??? down from a {fmtPct(HEADLINE.peakQuitsRate2021, 1)} peak
        </p>
        <p className="mt-1 max-w-3xl text-sm text-slate-300">
          Hires {fmtK(HEADLINE.hiresThousands)} ({fmtPct(HEADLINE.hiresRate)})
          nearly match separations {fmtK(HEADLINE.separationsThousands)} (
          {fmtPct(HEADLINE.separationsRate)}). Quit share of separations:{" "}
          {fmtPct(HEADLINE.quitShareOfSeparations * 100, 0)}.
        </p>
      </div>

      <div className="flex flex-col gap-3 rounded-xl border border-slate-200 bg-slate-50 p-3 sm:p-4">
        <ToggleGroup
          label="Panel"
          value={panel}
          options={PANEL_OPTIONS}
          onChange={setPanel}
        />
        {(panel === "flow") && (
          <ToggleGroup
            label="Era"
            value={era}
            options={ERA_OPTIONS}
            onChange={setEra}
          />
        )}
        {(panel === "industry" || panel === "scatter") && (
          <>
            <ToggleGroup
              label="Sector"
              value={sector}
              options={SECTOR_OPTIONS}
              onChange={setSector}
            />
            {panel === "industry" && (
              <ToggleGroup
                label="Metric"
                value={metric}
                options={METRIC_OPTIONS}
                onChange={setMetric}
              />
            )}
          </>
        )}
      </div>

      {panel === "flow" && (
        <ChartCard
          title="Hires, quits, layoffs, and openings"
          subtitle="Seasonally adjusted rates, total nonfarm ??? Great Resignation peak to June 2026 unwind"
        >
          <div data-viz={VIZ_MARKERS.flowTape} className="h-[360px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={flowData} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis dataKey="ym" tick={{ fontSize: 11 }} interval="preserveStartEnd" />
                <YAxis
                  tick={{ fontSize: 11 }}
                  unit="%"
                  domain={[0, (dataMax: number) => Math.max(8, Math.ceil(dataMax + 1))]}
                />
                <Tooltip
                  formatter={(v: number, name: string) => [fmtPct(v), name]}
                  labelFormatter={(l) => String(l)}
                />
                <Legend />
                <Line
                  type="monotone"
                  dataKey="openings"
                  name="Openings"
                  stroke={COLORS.openings}
                  strokeWidth={2}
                  dot={false}
                />
                <Line
                  type="monotone"
                  dataKey="hires"
                  name="Hires"
                  stroke={COLORS.hires}
                  strokeWidth={2}
                  dot={false}
                />
                <Line
                  type="monotone"
                  dataKey="quits"
                  name="Quits"
                  stroke={COLORS.quits}
                  strokeWidth={2.5}
                  dot={false}
                />
                <Line
                  type="monotone"
                  dataKey="layoffs"
                  name="Layoffs"
                  stroke={COLORS.layoffs}
                  strokeWidth={2}
                  dot={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            March???April 2020 layoff spike truncated visually only in the sense that the
            axis expands ??? cells are disclosed. Filter era to isolate the unwind.
          </p>
        </ChartCard>
      )}

      {panel === "industry" && (
        <ChartCard
          title={
            metric === "quitShare"
              ? "Quit share of separations by industry"
              : metric === "levels"
                ? "Quits vs layoffs (thousands)"
                : "Quits minus layoffs (rate wedge)"
          }
          subtitle="June 2026 (p) ?? sorted by quit???layoff rate wedge"
        >
          <div data-viz={VIZ_MARKERS.industryMix} className="h-[420px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              {metric === "quitShare" ? (
                <BarChart
                  layout="vertical"
                  data={industryChart}
                  margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
                >
                  <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                  <XAxis type="number" unit="%" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={110}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v: number) => fmtPct(v)} />
                  <Legend />
                  <Bar dataKey="quitShare" name="Quit share" fill={COLORS.quits} stackId="a" />
                  <Bar
                    dataKey="layoffShare"
                    name="Layoff share"
                    fill={COLORS.layoffs}
                    stackId="a"
                  />
                </BarChart>
              ) : metric === "levels" ? (
                <BarChart
                  layout="vertical"
                  data={industryChart}
                  margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
                >
                  <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={110}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="quits" name="Quits (000s)" fill={COLORS.quits} />
                  <Bar dataKey="layoffs" name="Layoffs (000s)" fill={COLORS.layoffs} />
                </BarChart>
              ) : (
                <BarChart
                  layout="vertical"
                  data={industryChart}
                  margin={{ top: 4, right: 16, left: 8, bottom: 4 }}
                >
                  <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                  <XAxis type="number" unit="%" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={110}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v: number, name: string) => [
                      fmtPct(Math.abs(v)),
                      name === "layoffs" ? "Layoffs rate" : name,
                    ]}
                  />
                  <Legend />
                  <Bar dataKey="quits" name="Quits rate" fill={COLORS.quits} stackId="wedge" />
                  <Bar
                    dataKey="layoffs"
                    name="Layoffs rate (???)"
                    fill={COLORS.layoffs}
                    stackId="wedge"
                  />
                </BarChart>
              )}
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "scatter" && (
        <ChartCard
          title="Who quits vs who gets laid off"
          subtitle="June 2026 industry rates ??? bubble size ??? hires rate (churn intensity)"
        >
          <div data-viz={VIZ_MARKERS.quitScatter} className="h-[380px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 12 }}>
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis
                  type="number"
                  dataKey="layoffsRate"
                  name="Layoffs rate"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  domain={[0, "auto"]}
                  label={{
                    value: "Layoffs & discharges rate (%)",
                    position: "insideBottom",
                    offset: -4,
                    fontSize: 11,
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="quitsRate"
                  name="Quits rate"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  domain={[0, "auto"]}
                  label={{
                    value: "Quits rate (%)",
                    angle: -90,
                    position: "insideLeft",
                    fontSize: 11,
                  }}
                />
                <ZAxis type="number" dataKey="hiresRate" range={[60, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v: number, name: string) =>
                    name === "hiresRate" ? [fmtPct(v), "Hires rate"] : [fmtPct(v), name]
                  }
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.label
                      ? String(payload[0].payload.label)
                      : ""
                  }
                />
                <Scatter data={scatterData} fill={COLORS.hires}>
                  {scatterData.map((d) => (
                    <Cell
                      key={d.id}
                      fill={
                        d.quitsRate > d.layoffsRate * 1.5
                          ? COLORS.quits
                          : d.layoffsRate > d.quitsRate
                            ? COLORS.layoffs
                            : COLORS.hires
                      }
                    />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Accommodation & food sits high on quits; information and construction lean
            layoff-heavy; finance is quiet on both axes.
          </p>
        </ChartCard>
      )}

      {panel === "size" && (
        <ChartCard
          title="Churn by establishment size"
          subtitle="Total private ?? June 2026 (p) ?? mid-size shops hire and quit fastest"
        >
          <div data-viz={VIZ_MARKERS.sizeClass} className="h-[360px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={sizeData} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} unit="%" />
                <Tooltip formatter={(v: number) => fmtPct(v)} />
                <Legend />
                <Bar dataKey="hires" name="Hires" fill={COLORS.hires} />
                <Bar dataKey="quits" name="Quits" fill={COLORS.quits} />
                <Bar dataKey="layoffs" name="Layoffs" fill={COLORS.layoffs} />
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 h-[220px] w-full">
            <p className="mb-2 text-sm font-semibold text-slate-700">
              Regional quit vs layoff rates
            </p>
            <ResponsiveContainer width="100%" height="90%">
              <BarChart data={regionData} margin={{ top: 4, right: 12, left: 0, bottom: 4 }}>
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} unit="%" />
                <Tooltip formatter={(v: number) => fmtPct(v)} />
                <Legend />
                <Bar dataKey="quits" name="Quits" fill={COLORS.quits} />
                <Bar dataKey="layoffs" name="Layoffs" fill={COLORS.layoffs} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "compose" && (
        <ChartCard
          title="What separations are made of"
          subtitle={`Total nonfarm ?? ${HEADLINE.separationsThousands.toLocaleString()}k separations in June 2026`}
        >
          <div className="grid gap-6 lg:grid-cols-2">
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={[...SEPARATION_COMPOSITION]}
                    dataKey="thousands"
                    nameKey="label"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={100}
                    paddingAngle={2}
                    label={({ label, share }) =>
                      `${label.split(" ")[0]} ${(share * 100).toFixed(0)}%`
                    }
                  >
                    {SEPARATION_COMPOSITION.map((s) => (
                      <Cell key={s.id} fill={s.color} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v: number, _n, p) => [
                      `${v.toLocaleString()}k (${fmtPct((p.payload.share as number) * 100, 0)})`,
                      p.payload.label as string,
                    ]}
                  />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex flex-col justify-center space-y-3 text-sm text-slate-700">
              <p>
                Quits still account for roughly{" "}
                <span className="font-semibold text-teal-800">
                  {fmtPct(HEADLINE.quitShareOfSeparations * 100, 0)}
                </span>{" "}
                of separations ??? the quit engine, not layoffs, is the main monthly
                turnover channel even after the Great Resignation cooled.
              </p>
              <p>
                Industry churn (hires + separations rates) spans{" "}
                <span className="font-semibold">
                  {Math.min(...INDUSTRIES.map(churnRate)).toFixed(1)}%
                </span>{" "}
                in government to{" "}
                <span className="font-semibold">
                  {Math.max(...INDUSTRIES.map(churnRate)).toFixed(1)}%
                </span>{" "}
                in leisure and hospitality.
              </p>
              <ul className="space-y-1 text-slate-600">
                {SEPARATION_COMPOSITION.map((s) => (
                  <li key={s.id} className="flex items-center gap-2">
                    <span
                      className="inline-block h-2.5 w-2.5 rounded-sm"
                      style={{ background: s.color }}
                    />
                    {s.label}: {s.thousands.toLocaleString()}k
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

