  { id: "west", label: "West", quitsRate: 2.1, layoffsRate: 1.1, separationsRate: 3.4, hiresRate: 3.3 },
];

/** Era bookmarks for flow-tape filtering */
export type EraId = "all" | "pre" | "shock" | "resignation" | "unwind";

export function eraForYm(ym: string): Exclude<EraId, "all"> {
  if (ym < "2020-03") return "pre";
  if (ym < "2021-03") return "shock";
  if (ym < "2023-01") return "resignation";
  return "unwind";
}

export function filterMonthlyByEra(era: EraId): MonthlyRates[] {
  if (era === "all") return MONTHLY_RATES;
  return MONTHLY_RATES.filter((r) => eraForYm(r.ym) === era);
}

export function quitShare(row: IndustryRow): number {
  if (row.separations <= 0) return 0;
  return row.quits / row.separations;
}

export function churnRate(row: IndustryRow): number {
  return row.hiresRate + row.separationsRate;
}

export function industriesBySector(sector: IndustrySector | "all"): IndustryRow[] {
  if (sector === "all") return INDUSTRIES;
  return INDUSTRIES.filter((i) => i.sector === sector);
}

/** Diverging quit-minus-layoff rate for bump chart */
export function quitMinusLayoff(row: IndustryRow): number {
  return row.quitsRate - row.layoffsRate;
}

/** Scatter pairs: quits rate vs layoffs rate */
export function scatterPairs(sector: IndustrySector | "all" = "all") {
  return industriesBySector(sector).map((i) => ({
    id: i.id,
    label: i.short,
    quitsRate: i.quitsRate,
    layoffsRate: i.layoffsRate,
    hiresRate: i.hiresRate,
    quitShare: quitShare(i),
    churn: churnRate(i),
    sector: i.sector,
  }));
}

/** Separation composition for donut (national, June 2026) */
export const SEPARATION_COMPOSITION = [
  { id: "quits", label: "Quits", thousands: 3_232, share: 3_232 / 5_351, color: "#0f766e" },
  { id: "layoffs", label: "Layoffs & discharges", thousands: 1_766, share: 1_766 / 5_351, color: "#b91c1c" },
  { id: "other", label: "Other separations", thousands: 353, share: 353 / 5_351, color: "#64748b" },
] as const;

/** Prose / table helpers */
export function industryTableRows() {
  return INDUSTRIES.map((i) => ({
    industry: i.label,
    hiresRate: i.hiresRate,
    quitsRate: i.quitsRate,
    layoffsRate: i.layoffsRate,
    quitSharePct: Math.round(quitShare(i) * 1000) / 10,
    churn: Math.round(churnRate(i) * 10) / 10,
  }));
}

