    await clickBtn(page, "Industry mix");
    await page.waitForSelector(`[data-viz="${VIZ_MARKERS.industryMix}"]`, {
      timeout: 10000,
    });
    await clickBtn(page, "Quit ?? layoff");
    await page.waitForSelector(`[data-viz="${VIZ_MARKERS.quitScatter}"]`, {
      timeout: 10000,
    });
    await clickBtn(page, "Size class");
    await page.waitForSelector(`[data-viz="${VIZ_MARKERS.sizeClass}"]`, {
      timeout: 10000,
